import { randomUUID } from 'node:crypto';
import { isDeepStrictEqual as same } from 'node:util';
import { parseIngredientAmount } from '../src/lib/recipes/ingredient-amount';

const finalRule = 'explicit-final-all-remaining-clause';
const absoluteRule = 'explicit-absolute-clause';
const escape = (text: string) => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const owned = (binding: any) => binding.payload?.relationshipEvidence?.rule === finalRule ||
  (binding.payload?.relationshipEvidence?.rule === absoluteRule && binding.payload?.allocationGroup);

/** Write-time companion for the bounded ordinary C05 Save scenario. */
export function discoverRemainderBindings(before: any, recipe: any) {
  const steps = recipe.instructionSections.flatMap((section: any) => section.steps);
  const previous = before.instructionSections.flatMap((section: any) => section.steps);
  for (const step of steps) step.bindings = step.bindings.filter((binding: any) => !owned(binding));
  for (const row of recipe.ingredientLines) {
    if (row.amount?.kind !== 'scalar' || row.scaling !== 'proportional' || row.package ||
        !row.unit?.text || !/^(g|kg|mg|ml|l|cup|cups|tasse|tasses|tsp|teaspoon|teaspoons|tbsp|tablespoon|tablespoons|c\. à thé|c\. à soupe)$/i.test(row.unit.text) ||
        !row.description?.trim() || /[\r\n.;:!?]/.test(row.description) ||
        recipe.ingredientLines.filter((other: any) => other.id === row.id || other.description.toLowerCase() === row.description.toLowerCase()).length !== 1) continue;
    const noun = escape(row.description);
    const mention = new RegExp(`(?<![\\p{L}\\p{N}])${noun}(?![\\p{L}\\p{N}])`, 'giu');
    const matches = steps.filter((step: any) => [...step.text.matchAll(mention)].length > 0);
    if (matches.length !== 2 || matches.some((step: any) => [...step.text.matchAll(mention)].length !== 1 || step.bindings.length || steps.filter((other: any) => other.id === step.id).length !== 1)) continue;
    const [prior, final] = matches;
    const measure = `(?<measurement>(?<amount>[0-9¼½¾⅐⅑⅒⅓⅔⅕⅖⅗⅘⅙⅚⅛⅜⅝⅞][0-9¼½¾⅐⅑⅒⅓⅔⅕⅖⅗⅘⅙⅚⅛⅜⅝⅞/.,–\\- \\t]*)[ \\t]+${escape(row.unit.text)})`;
    const first = new RegExp(`^[ \\t]*(?:(?:Add|Use|Cook|Boil|Mix)[ \\t]+${measure}[ \\t]+(?:of[ \\t]+)?${noun}|(?:Ajouter|Ajoutez|Utiliser|Utilisez|Cuire|Faire cuire|Faites cuire|Mélanger|Mélangez)[ \\t]+(?<frMeasurement>(?<frAmount>[0-9¼½¾⅐⅑⅒⅓⅔⅕⅖⅗⅘⅙⅚⅛⅜⅝⅞][0-9¼½¾⅐⅑⅒⅓⅔⅕⅖⅗⅘⅙⅚⅛⅜⅝⅞/.,–\\- \\t]*)[ \\t]+${escape(row.unit.text)})[ \\t]+(?:de[ \\t]+|d['’])?${noun})\\.?[ \\t]*$`, 'iu').exec(prior.text);
    const last = new RegExp(`^[ \\t]*(?:Finally,[ \\t]+(?:use|add)[ \\t]+all[ \\t]+the[ \\t]+remaining[ \\t]+${noun}|Enfin,[ \\t]+(?:utilisez|ajoutez)[ \\t]+tout[ \\t]+le[ \\t]+reste[ \\t]+(?:de[ \\t]+|d['’])${noun})\\.?[ \\t]*$`, 'iu').exec(final.text);
    if (!first || !last) continue;
    const amount = parseIngredientAmount((first.groups!.amount ?? first.groups!.frAmount).trim());
    if (amount?.kind !== 'scalar' || amount.value!.n === '0' ||
        BigInt(row.amount.value.n) * BigInt(amount.value!.d!) < BigInt(amount.value!.n!) * BigInt(row.amount.value.d)) continue;
    // An unqualified partial/conditional statement elsewhere can affect this row.
    const partial = /\b(half|remaining|remainder|rest|reserve|reserved|except|unless|some|part|divided|each|per|alternatively|or|if|not|never|moitié|reste|restant|restante|réserver|réservez|sauf|chaque|par|ou|si|pas|jamais)\b/iu;
    if (steps.some((step: any) => step !== final && partial.test(step.text))) continue;
    const oldRow = before.ingredientLines.find((other: any) => other.id === row.id);
    const unchanged = (step: any) => previous.find((old: any) => old.id === step.id && old.text === step.text && old.textRevision === step.textRevision);
    const meaningSame = oldRow && ['description', 'unit', 'scaling', 'package', 'shopping'].every((key) => same(oldRow[key], row[key]));
    const oldPrior = meaningSame && unchanged(prior)?.bindings.find((binding: any) => owned(binding) && binding.role === 'absolute');
    const priorId = oldPrior?.id ?? randomUUID();
    const oldFinal = oldPrior && unchanged(final)?.bindings.find((binding: any) => owned(binding) && binding.payload?.predecessors?.[0] === priorId);
    const finalId = oldFinal?.id ?? randomUUID();
    const group = { id: oldPrior?.payload.allocationGroup.id ?? randomUUID(), exhaustive: true, bindingIds: [priorId, finalId] };
    const measurement = first.groups!.measurement ?? first.groups!.frMeasurement;
    const remainder = /remaining|reste/iu.exec(final.text)!;
    const bind = (step: any, id: string, role: string, text: string, start: number, payload: any) => ({
      id, ingredientLineId: row.id, stepId: step.id, role, status: 'validated',
      validatedContentRevision: recipe.contentRevision, validatedTextRevision: step.textRevision,
      span: { start, end: start + text.length, expectedText: text },
      payload: { relationshipEvidence: { version: 1, rule: role === 'remainder' ? finalRule : absoluteRule, sourceRevision: 'mock-source', originalAmount: amount }, allocationGroup: group, ...payload },
    });
    prior.bindings = [bind(prior, priorId, 'absolute', measurement, prior.text.indexOf(measurement), { amount, unit: row.unit })];
    final.bindings = [bind(final, finalId, 'remainder', remainder[0], remainder.index, { allocationGroupId: group.id, predecessors: [priorId] })];
  }
}
